on conflict do nothing;
update public.sand_filter_models set source = case source
  when 'S1' then 'SHFFG Technical Data Sheet R 2/9/18; PART NUMBERS - MODEL NUMBERS.xlsx; master_product_list'
  when 'S2' then 'SRF/DRF Single Cell Sand Filters tech data R-5/4/11; master_product_list'
  when 'S3' then 'SRF/DRF Single Cell Sand Filters tech data R-5/4/11'
  when 'S4' then 'CCFG Legacy tech data ML-4/29/26; drawing 36CCFG-3MAN; CCFG NSF PIF 2.7.25; master_product_list' end
where source in ('S1','S2','S3','S4');
update public.sand_filter_models set notes = 'A = inside diameter (34 in models: 34 in is OD), A1 = max OD, B = overall length, C = overall height, E = lower connection height, G = stacked overall height. 50 psi FG, tested to 1.1x, 4:1 safety factor.' where product_line='SHFFG' and notes is null;
update public.sand_filter_models set notes = 'Dual cell: two SRF cells of the same diameter on one face piping set with isolation valves. K = overall width, L = face piping depth.' where product_line='DRF' and notes is null;
update public.sand_filter_models set notes = 'Steel SRF dimensions (50 psi, 75 psi hydro). Fiberglass SRFFG (50 psi, 60 or 72 in side shell) listed with connection sizes ' || replace(notes,'FG:','') || '. Bed: 22 in sand over gravel to the top of the laterals.' where product_line='SRF' and notes like 'FG:%';
